mapper.sql:
SELECT '账平' AS category, t.bill_date AS bill_date, t.insutype AS insur_type, DECODE(t.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, COUNT(t.setl_id) AS qty, SUM(t.medfee_sumamt) AS medfee_sumamt, SUM(t.acct_pay) AS acct_pay, SUM(t.hlfp_pay) AS hlfp_pay, SUM(t.cash_pay) AS cash_pay, SUM(t.cvlserv_pay) AS cvlserv_pay, SUM(t.hlfes_pay) AS hlfes_pay, SUM(t.hlfmi_pay) AS hlfmi_pay, SUM(t.hlfob_pay) AS hlfob_pay, SUM(t.maf_pay) AS maf_pay, SUM(t.oth_pay) AS oth_pay FROM ips_dz_biz_bills t WHERE t.zp_flag = 1 AND t.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND t.insutype = #{insurType}
GROUP BY t.insutype, t.bill_date UNION ALL SELECT '医保负金额-退费' AS category, b.bill_date AS bill_date, b.insutype AS insur_type, DECODE(b.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, COUNT(b.setl_id) AS qty, SUM(b.medfee_sumamt) AS medfee_sumamt, SUM(b.acct_pay) AS acct_pay, SUM(b.hlfp_pay) AS hlfp_pay, SUM(b.cash_pay) AS cash_pay, SUM(b.cvlserv_pay) AS cvlserv_pay, SUM(b.hlfes_pay) AS hlfes_pay, SUM(b.hlfmi_pay) AS hlfmi_pay, SUM(b.hlfob_pay) AS hlfob_pay, SUM(b.maf_pay) AS maf_pay, SUM(b.oth_pay) AS oth_pay FROM ips_dz_pay_bills b INNER JOIN ips_dz_biz_bills a ON a.INSUTYPE = b.INSUTYPE AND a.TRAN_TYPE = 1 AND a.mdtrt_id = b.mdtrt_id AND a.medfee_sumamt = -b.medfee_sumamt AND a.bill_date <= b.bill_date AND a.bill_date BETWEEN TO_DATE(#{prevStart}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd') WHERE b.TRAN_TYPE = 2 AND b.zp_flag = -1 AND b.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND b.insutype = #{insurType}
GROUP BY b.insutype, b.bill_date UNION ALL SELECT '医保正金额-收费' AS category, a.bill_date AS bill_date, a.insutype AS insur_type, DECODE(a.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, COUNT(a.setl_id) AS qty, SUM(a.medfee_sumamt) AS medfee_sumamt, SUM(a.acct_pay) AS acct_pay, SUM(a.hlfp_pay) AS hlfp_pay, SUM(a.cash_pay) AS cash_pay, SUM(a.cvlserv_pay) AS cvlserv_pay, SUM(a.hlfes_pay) AS hlfes_pay, SUM(a.hlfmi_pay) AS hlfmi_pay, SUM(a.hlfob_pay) AS hlfob_pay, SUM(a.maf_pay) AS maf_pay, SUM(a.oth_pay) AS oth_pay FROM ips_dz_pay_bills a WHERE a.TRAN_TYPE = 1 AND a.zp_flag = -1 AND a.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND a.insutype = #{insurType}
GROUP BY a.insutype, a.bill_date

mapper.select:
SELECT b.insutype AS insur_type, DECODE(b.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, COUNT(b.setl_id) AS refund_total, SUM(CASE WHEN a.setl_id IS NOT NULL AND TO_CHAR(a.bill_date, 'yyyy-mm') != TO_CHAR(b.bill_date, 'yyyy-mm') THEN 1 ELSE 0 END) AS cross_cnt, SUM(CASE WHEN a.setl_id IS NULL THEN 1 ELSE 0 END) AS none_cnt FROM ips_dz_pay_bills b LEFT JOIN ips_dz_biz_bills a ON a.INSUTYPE = b.INSUTYPE AND a.TRAN_TYPE = 1 AND a.mdtrt_id = b.mdtrt_id AND a.medfee_sumamt = -b.medfee_sumamt AND a.bill_date <= b.bill_date AND a.bill_date BETWEEN TO_DATE(#{prevStart}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd') WHERE b.TRAN_TYPE = 2 AND b.zp_flag = -1 AND b.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND b.insutype = #{insurType}
GROUP BY b.insutype, d.insutype_name ORDER BY b.insutype
